mapper.select:
SELECT game_id, skill_key, name, description, max_level, status, sort_order, created_at, updated_at
FROM public.skills
WHERE game_id = #{gameId}

    AND (
        strpos(lower(skill_key), lower(#{keyword})) > 0
        OR strpos(lower(name), lower(#{keyword})) > 0
    )


    AND status = #{status}

ORDER BY sort_order ASC, name ASC, skill_key ASC

SELECT game_id, skill_key, name, description, max_level, status, sort_order, created_at, updated_at
FROM public.skills
WHERE game_id = #{gameId} AND skill_key = #{skillKey}

SELECT COUNT(1)
FROM public.skills
WHERE game_id = #{gameId} AND skill_key = #{skillKey}

mapper.insert:
INSERT INTO public.skills (
    game_id, skill_key, name, description, max_level, status, sort_order
) VALUES (
    #{gameId}, #{skillKey}, #{name}, #{description}, #{maxLevel}, #{status}, #{sortOrder}
)

mapper.select:
SELECT r.skill_key, r.skill_category_key FROM public.skill_category_relations r INNER JOIN public.skill_categories c ON c.game_id = r.game_id AND c.skill_category_key = r.skill_category_key WHERE r.game_id = #{gameId} AND r.skill_key IN
#{skillKey}
ORDER BY r.skill_key ASC, c.sort_order ASC, c.name ASC, r.skill_category_key ASC

SELECT skill_category_key
FROM public.skill_category_relations
WHERE game_id = #{gameId} AND skill_key = #{skillKey}

SELECT skill_category_key, status FROM public.skill_categories WHERE game_id = #{gameId} AND skill_category_key IN
#{key}
ORDER BY skill_category_key ASC FOR UPDATE

mapper.insert:
INSERT INTO public.skill_category_relations (
    game_id, skill_key, skill_category_key
) VALUES (
    #{gameId}, #{skillKey}, #{skillCategoryKey}
)

mapper.delete:
